{
  "part": {
    "name": "Tapered linkage arm with clevis and hook end",
    "description": "Long tapered arm/lever with a forked clevis (split lug) pin-joint interface on one end and a rounded hooked/seat interface on the opposite end. Prismatic body with drafted faces and localized cylindrical features at both ends.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Largely symmetric about the mid-plane y=0 (left/right across width), with paired clevis lugs and mirrored side geometry. Not symmetric along length (different end interfaces)."
  },
  "Section": [
    {
      "id": "SEC_01",
      "name": "Clevis fork / pin-joint end",
      "features included": [
        "Split fork with central slot (clevis opening)",
        "Two coaxial pin holes (one per lug)",
        "Outer rounded lug ends (cylindrical perimeter)",
        "Inner lug faces defining slot width",
        "Slot end wall / stop face"
      ],
      "function intent": "Provide a pin-joint mounting interface to connect the arm to a mating clevis/pin assembly while allowing rotation about the pin axis.",
      "physical behavior": "Transfers primarily shear and bearing loads through the lug holes into the arm; the split lugs resist spreading via section thickness and surrounding material, while rounded outer ends reduce stress concentrations at the lug tips.",
      "geometry": "Two parallel lugs separated by a rectangular slot; each lug has a cylindrical through-hole. Lug tips have a larger-radius cylindrical outer profile; the slot terminates at a planar end wall.",
      "location": "Left end of the part (negative X extreme, around x ≈ -75.75 mm).",
      "colour": {
        "R": 220,
        "G": 60,
        "B": 60
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Upper lug pin-hole cylinder",
          "Brep_id": "FACE 0",
          "description": "Cylindrical bore surface for the pin in the upper lug (axis along Y, r=3)."
        },
        {
          "face_code": "0001",
          "name": "Lower lug pin-hole cylinder",
          "Brep_id": "FACE 1",
          "description": "Cylindrical bore surface for the pin in the lower lug (axis along Y, r=3)."
        },
        {
          "face_code": "0002",
          "name": "Slot end wall",
          "Brep_id": "FACE 2",
          "description": "Planar wall closing the clevis slot at its inner end (plane normal -X)."
        },
        {
          "face_code": "0003",
          "name": "Inner face of lower lug (slot side)",
          "Brep_id": "FACE 3",
          "description": "Planar inner side face defining one side of the clevis slot (y=-3.5)."
        },
        {
          "face_code": "0004",
          "name": "Inner face of upper lug (slot side)",
          "Brep_id": "FACE 4",
          "description": "Planar inner side face defining the other side of the clevis slot (y=+3.5)."
        },
        {
          "face_code": "0005",
          "name": "Outer perimeter cylinder of lower lug tip",
          "Brep_id": "FACE 6",
          "description": "Large-radius cylindrical outer surface forming the rounded end of the lower lug (axis along Y, r=7.5)."
        },
        {
          "face_code": "0006",
          "name": "Outer perimeter cylinder of upper lug tip",
          "Brep_id": "FACE 15",
          "description": "Large-radius cylindrical outer surface forming the rounded end of the upper lug (axis along Y, r=7.5)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_01",
          "target id": "SEC_02",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_01",
          "target id": "SEC_02",
          "function relationship": "constrains_dof",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "SEC_02",
      "name": "Tapered arm body",
      "features included": [
        "Long tapered/prismatic beam (planar skin faces)",
        "Drafted top and bottom faces",
        "Drafted side faces (left/right)",
        "Stress-carrying spine between end interfaces"
      ],
      "function intent": "Transmit load/motion between the clevis end and the hook end while minimizing mass via taper and maintaining stiffness.",
      "physical behavior": "Acts as a beam in bending and axial tension/compression; taper and drafted faces distribute stresses and reduce peak bending stress toward the thinner end while maintaining adequate section near the clevis end.",
      "geometry": "Four dominant long planar faces (top, bottom, and two side faces) forming a tapered solid that transitions between the two end interfaces; faces are slightly angled (draft) relative to global axes.",
      "location": "Central span connecting left clevis end to right hook end (dominant length along X).",
      "colour": {
        "R": 60,
        "G": 170,
        "B": 80
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Bottom face (drafted)",
          "Brep_id": "FACE 11",
          "description": "Large planar bottom surface of the arm/body with slight draft (normal mostly -Z)."
        },
        {
          "face_code": "0008",
          "name": "Left side face (negative Y side)",
          "Brep_id": "FACE 9",
          "description": "Large planar side surface on -Y side; slightly drafted (normal mostly -Y)."
        },
        {
          "face_code": "0009",
          "name": "Top face (drafted)",
          "Brep_id": "FACE 5",
          "description": "Large planar top surface of the arm/body with slight draft (normal mostly +Z)."
        },
        {
          "face_code": "0010",
          "name": "Right side face (positive Y side)",
          "Brep_id": "FACE 16",
          "description": "Large planar side surface on +Y side; slightly drafted (normal mostly +Y)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_02",
          "target id": "SEC_01",
          "function relationship": "distributes_stress",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_02",
          "target id": "SEC_03",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_02",
          "target id": "SEC_03",
          "function relationship": "provides_clearance",
          "structural relationship": "adjacent_to"
        }
      ]
    },
    {
      "id": "SEC_03",
      "name": "Hook / rounded end interface",
      "features included": [
        "Rounded end boss (large cylindrical outer surface)",
        "Concave seat/notch (cylindrical groove/relief)",
        "End cap/top pad surface",
        "Local side/end faces defining the open notch",
        "Small-radius cylindrical edge/round feature"
      ],
      "function intent": "Provide an engagement/seat feature at the tip of the arm for hooking onto or locating a mating rod/cable/feature, while providing clearance for insertion and contact on curved surfaces.",
      "physical behavior": "Carries localized contact forces at the seat/notch and transfers them into the arm; curved outer boss reduces edge contact and stress concentration; end faces bound the notch and help constrain lateral motion of the mating feature.",
      "geometry": "A bulb/rounded end defined by a large-radius cylindrical outer surface, with a smaller-radius cylindrical concavity/seat and additional small cylindrical patch; bounded by small planar end faces and a top planar face.",
      "location": "Right end of the part (positive X extreme, around x ≈ +75.75 mm).",
      "colour": {
        "R": 80,
        "G": 120,
        "B": 210
      },
      "major_faces": [
        {
          "face_code": "0011",
          "name": "Outer rounded boss cylinder",
          "Brep_id": "FACE 10",
          "description": "Large cylindrical outer surface forming the rounded end/bulb (axis along Y, r=9)."
        },
        {
          "face_code": "0012",
          "name": "Concave seat / notch cylinder",
          "Brep_id": "FACE 7",
          "description": "Smaller cylindrical surface forming the inner seat/notch curvature (axis along Y, r=3)."
        },
        {
          "face_code": "0013",
          "name": "Small cylindrical patch near top of end",
          "Brep_id": "FACE 8",
          "description": "Short cylindrical surface segment (axis along Y, r=3) associated with local rounding/transition at the end feature."
        },
        {
          "face_code": "0014",
          "name": "Top end pad face",
          "Brep_id": "FACE 17",
          "description": "Planar top face at z=15 forming the top boundary of the end feature."
        },
        {
          "face_code": "0015",
          "name": "End-side face (positive Y, small)",
          "Brep_id": "FACE 14",
          "description": "Small planar face at y=+3 bounding the end feature/notch region."
        },
        {
          "face_code": "0016",
          "name": "Vertical end rounding cylinder",
          "Brep_id": "FACE 13",
          "description": "Cylindrical surface with axis along Z (r=3) forming a rounded vertical edge at the extreme end."
        },
        {
          "face_code": "0017",
          "name": "End-side face (negative Y, small)",
          "Brep_id": "FACE 12",
          "description": "Small planar face at y=-3 bounding the end feature/notch region."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_03",
          "target id": "SEC_02",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_03",
          "target id": "SEC_02",
          "function relationship": "locates_mating_part",
          "structural relationship": "adjacent_to"
        }
      ]
    }
  ]
}
